insert into public.properties (id, title, price, type, status, city, district, bedrooms, bathrooms, land_area, building_area, certificate, floors, parking, year_built, furnished, electricity, description, photos, agent_name, agent_photo, whatsapp, is_sold, is_featured, view_count, created_at)
values
  (md5('rumah-minimalis-bintaro')::uuid, 'Rumah Minimalis 2 Lantai di Bintaro', 850000000, 'rumah', 'dijual', 'Jakarta Selatan', 'Bintaro Jaya', 3, 2, 120, 90, 'SHM', 2, 1, 2021, false, 2200, 'Rumah modern siap huni di kawasan Bintaro Jaya dengan desain minimalis, pencahayaan alami, dan akses mudah ke pusat Jakarta. Bangunan baru, bersih, serta berada di lingkungan keluarga yang aman dan nyaman.', ARRAY['https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=800&q=80']::text[], 'Budi Santoso', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=300&q=80', '6281234567890', false, true, 486, '2026-11-05T08:00:00.000Z'),
  (md5('apartemen-sudirman-3-kamar')::uuid, 'Apartemen Sudirman 3 Kamar Lengkap Perabot', 1750000000, 'apartemen', 'dijual', 'Jakarta Pusat', 'Setiabudi', 3, 2, 0, 126, 'HGB', 1, 1, 2020, true, 4400, 'Hunian premium di jantung Jakarta dengan furnishing lengkap, suasana nyaman, dan akses langsung ke MRT. Unit siap tinggal dan cocok untuk profesional maupun keluarga kecil.', ARRAY['https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560185007-cde436f6a4d0?auto=format&fit=crop&w=800&q=80']::text[], 'Sari Wijaya', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=300&q=80', '6282234567890', false, true, 720, '2026-11-03T10:30:00.000Z'),
  (md5('rumah-classic-bekasi')::uuid, 'Rumah Classy di Metropolitan Bekasi', 625000000, 'rumah', 'dijual', 'Bekasi', 'Metropolitan', 4, 3, 180, 140, 'SHM', 2, 2, 2018, false, 4400, 'Rumah hook dua lantai dengan halaman depan dan belakang di kawasan Metropolitan Bekasi. Kamar tidur nyaman, ruang keluarga lapang, dapur terpisah, serta alamat strategis dekat pusat komersial dan sekolah.', ARRAY['https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=800&q=80']::text[], 'Andi Pratama', 'https://images.unsplash.com/photo-1568602471122-7832951cc4c5?auto=format&fit=crop&w=300&q=80', '6283234567890', false, false, 315, '2026-10-28T06:00:00.000Z'),
  (md5('rumah-tejas-ragunan')::uuid, 'Rumah Satu Lantai di Ragunan', 975000000, 'rumah', 'dijual', 'Jakarta Selatan', 'Ragunan', 3, 2, 150, 100, 'SHM', 1, 2, 2017, true, 2200, 'Rumah satu lantai dengan desain tejas yang hangat di Ragunan. Halaman luas cocok untuk keluarga, seluruh perabot sudah tersedia, serta lokasi strategis dekat sekolah, pasar, dan akses tol outer Jakarta.', ARRAY['https://images.unsplash.com/photo-1570129477492-45c003edd2be?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600210491892-03d54c0aaf87?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600566752355-35792bedcfea?auto=format&fit=crop&w=800&q=80']::text[], 'Dewi Lestari', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=300&q=80', '6284234567890', false, true, 562, '2026-11-06T09:15:00.000Z'),
  (md5('tanah-strategi-depok')::uuid, 'Tanah Strategis di Depok', 450000000, 'tanah', 'dijual', 'Depok', 'Margonda', 0, 0, 200, 0, 'SHM', 0, 0, 0, false, 0, 'Tanah kavling di Margonda dengan akses jalan lebar dan posisi strategis dekat pusat kota Depok. Cocok untuk dibangun rumah, kos-kosan, atau unit usaha. Dokumen SHM dan batas jelas.', ARRAY['https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1449844908441-8829872d2607?auto=format&fit=crop&w=800&q=80']::text[], 'Raka Saputra', 'https://images.unsplash.com/photo-1566492031773-4f4e44671857?auto=format&fit=crop&w=300&q=80', '6285234567890', false, false, 201, '2026-10-20T07:00:00.000Z'),
  (md5('apartemen-kelapa-gading')::uuid, 'Apartemen 2 Kamar di Kelapa Gading', 720000000, 'apartemen', 'dijual', 'Jakarta Utara', 'Kelapa Gading', 2, 1, 0, 78, 'HGB', 1, 1, 2019, true, 2200, 'Apartemen 2 kamar dengan interior bersih dan pencahayaan yang terang. Berada di kawasan Kelapa Gading yang strategis, dekat mall, sekolah, serta akses tol luar Jakarta.', ARRAY['https://images.unsplash.com/photo-1493809842364-78817add7ffb?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1554995207-c18c203602cb?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560185007-cde436f6a4d0?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560185127-6ed189bf02f4?auto=format&fit=crop&w=800&q=80']::text[], 'Maya Anggraini', 'https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=300&q=80', '6286234567890', false, false, 342, '2026-10-30T12:00:00.000Z'),
  (md5('ruko-biz-jakarta-barat')::uuid, 'Ruko 2 Lantai untuk Usaha di Jakarta Barat', 2100000000, 'ruko', 'dijual', 'Jakarta Barat', 'Gading', 0, 2, 240, 300, 'SHM', 2, 4, 2016, false, 6600, 'Ruko dua lantai dengan area parkir luas dan akses jalan raya di Jakarta Barat. Cocok untuk kantor, toko, atau klinik dengan visibilitas tinggi dan area yang fleksibel.', ARRAY['https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=800&q=80']::text[], 'Fajar Nugroho', 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=300&q=80', '6287234567890', false, true, 610, '2026-11-01T08:45:00.000Z'),
  (md5('kost-exclusive-pusat-jakarta')::uuid, 'Kost Eksklusif Dekat KRL', 320000000, 'kost', 'disewa', 'Jakarta Pusat', 'Menteng', 1, 1, 150, 180, 'HGB', 3, 2, 2022, true, 4400, 'Kost eksklusif dengan kamar mandi dalam, meja belajar, dan layanan harian. Lokasinya dekat KRL serta pusat Jakarta, cocok untuk mahasiswa atau pekerja yang ingin tinggal di area strategis.', ARRAY['https://images.unsplash.com/photo-1555854877-bab0e564b8d5?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560448204-602b3c5a4c6b?auto=format&fit=crop&w=800&q=80']::text[], 'Nadia Putri', 'https://images.unsplash.com/photo-1594744803329-e58b31de8bf5?auto=format&fit=crop&w=300&q=80', '6288234567890', false, false, 274, '2026-10-25T05:30:00.000Z'),
  (md5('villa-bogor-barureg')::uuid, 'Villa Modern di Barureg, Bogor', 2850000000, 'villa', 'dijual', 'Bogor', 'Barureg', 5, 5, 400, 350, 'SHM', 2, 4, 2023, true, 6600, 'Villa modern dengan kolam renang pribadi, taman luas, dan desain elegan di Barureg, Bogor. Lingkungan asri dengan udara segar pegunungan, keamanan 24 jam, serta akses mudah ke pusat kota dan kawasan wisata sekitar.', ARRAY['https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600566752355-35792bedcfea?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600607688960-e095ff83135c?auto=format&fit=crop&w=800&q=80']::text[], 'Dimas Prasetyo', 'https://images.unsplash.com/photo-1564564321837-a57b7070ac4f?auto=format&fit=crop&w=300&q=80', '6289234567890', false, true, 895, '2026-11-04T11:20:00.000Z'),
  (md5('rumah-mewah-cakung')::uuid, 'Rumah Mewah di Cakung, Jakarta Timur', 1150000000, 'rumah', 'dijual', 'Jakarta Timur', 'Cakung', 4, 3, 210, 165, 'SHM', 2, 2, 2020, false, 4400, 'Rumah berfasilitas lengkap dengan ruang keluarga yang luas, dapur modern, dan taman privasi. Lokasi di Cakung sangat strategis dekat pusat kota serta akses ke berbagai jalan utama.', ARRAY['https://images.unsplash.com/photo-1600047509358-9dc75507daeb?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1600566752229-250ed79470f8?auto=format&fit=crop&w=800&q=80']::text[], 'Olivia Tan', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80', '6291234567890', false, false, 437, '2026-10-31T04:45:00.000Z'),
  (md5('apartemen-alam-imut-tangerang')::uuid, 'Apartemen 1 Kamar di Alam Imut', 350000000, 'apartemen', 'terjual', 'Tangerang', 'Alam Imut', 1, 1, 0, 45, 'HGB', 1, 1, 2022, true, 2200, 'Apartemen satu kamar yang nyaman dan sudah dilengkapi perabot, cocok untuk pekerja atau pasangan muda. Berada di kawasan Alam Imut dengan fasilitas lengkap serta harga yang masih kompetitif.', ARRAY['https://images.unsplash.com/photo-1560185008-b033106af5c3?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1560185127-6ed189bf02f4?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=800&q=80']::text[], 'Hendra Gunawan', 'https://images.unsplash.com/photo-1531384441138-2736e62e0919?auto=format&fit=crop&w=300&q=80', '6292234567890', true, false, 178, '2026-10-18T10:00:00.000Z'),
  (md5('tanah-kavling-sukaraja-bandung')::uuid, 'Tanah Kavling di Sukaraja, Bandung', 290000000, 'tanah', 'dijual', 'Bandung', 'Sukaraja', 0, 0, 150, 0, 'SHM', 0, 0, 0, false, 0, 'Tanah kavling di Sukaraja dengan lingkungan yang asri dan jalan penghubung yang baik. Potensi cocok untuk rumah tinggal, kios, atau rumah tamu dengan pendapatan sewa yang menarik.', ARRAY['https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1449844908441-8829872d2607?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=800&q=80']::text[], 'Tika Rahmawati', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=300&q=80', '6293234567890', false, false, 125, '2026-10-12T09:00:00.000Z')
